function shell(){document.body.innerHTML=`<div class="app-shell"><header class="app-top"><button class="app-brand" data-act="home" type="button" aria-label="Return to homepage">BM4 SBA Studio</button><span class="top-status" id="topStatus"></span><span id="timer"></span><span class="pace" id="pace"></span><button class="icon-btn" data-act="ranges">▤ Ranges</button><button class="icon-btn" data-act="theme">◐</button><button class="icon-btn" data-act="settings">⚙</button></header><main class="view" id="view"></main><aside class="ranges-panel" id="rangesPanel" aria-hidden="true"><div class="ranges-panel-head"><div><span class="eyebrow">UK adult intervals</span><h2>Reference Ranges</h2></div><button class="v2-btn" data-act="close-ranges" type="button">Close</button></div><div class="range-panel-note"><b>Lab intervals vary.</b> Prefer the range printed with the patient result.</div><input id="rangePanelQuery" class="search-input" placeholder="Search e.g. potassium, INR, TSH"><div class="ranges-panel-body" id="rangePanelBody"></div></aside></div><dialog class="modal-v2" id="modal"></dialog>`;document.body.onclick=globalClick;document.querySelector('.app-brand').onclick=e=>{e.preventDefault();e.stopPropagation();closeRanges();pauseSession();view='home';viewAttempt=null;render()};setTheme();render()}
